 document.body.insertAdjacentHTML('beforeend',`<div class="modal fade" id="${mid}" tabindex="-1"><div class="modal-dialog modal-xl modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h5 class="modal-title text-truncate" id="${mid}t"></h5><div class="ms-auto d-flex gap-2 align-items-center flex-shrink-0"><button class="btn btn-icon btn-light" id="${mid}p" title="Previous" aria-label="Previous"><i class="bx bx-chevron-left"></i></button><small id="${mid}c" class="text-muted"></small><button class="btn btn-icon btn-light" id="${mid}n" title="Next" aria-label="Next"><i class="bx bx-chevron-right"></i></button><a class="btn btn-icon btn-soft-primary" id="${mid}d" title="Download" aria-label="Download"><i class="bx bx-download"></i></a><a class="btn btn-icon btn-light" id="${mid}o" target="_blank" rel="noopener" title="Open in new tab" aria-label="Open in new tab"><i class="bx bx-link-external"></i></a><button class="btn-close ms-2" data-bs-dismiss="modal"></button></div></div><div class="modal-body p-0 text-center bg-light" id="${mid}b" style="height:75vh;overflow:auto"></div></div></div></div>`);
 const el=document.getElementById(mid),g=s=>el.querySelector('#'+mid+s);
 const show=()=>{const f=list[i];g('t').textContent=f.filename;g('c').textContent=(i+1)+' / '+list.length;g('d').href='/api/files/'+f.id;g('o').href='/api/files/'+f.id+'?inline=1';
  g('b').innerHTML=/pdf/i.test(f.mime)?`<iframe src="/api/files/${f.id}?inline=1" style="width:100%;height:100%;border:0"></iframe>`:`<img src="/api/files/${f.id}?inline=1" alt="" style="max-width:100%;max-height:100%;object-fit:contain" class="p-2">`;g('p').disabled=i===0;g('n').disabled=i===list.length-1};
 g('p').onclick=()=>{i--;show()};g('n').onclick=()=>{i++;show()};const kd=e=>{if(e.key==='ArrowLeft'&&i>0){i--;show()}if(e.key==='ArrowRight'&&i<list.length-1){i++;show()}};document.addEventListener('keydown',kd);
