function modal(title,body,ok,onOk){const id='m'+Date.now();document.body.insertAdjacentHTML('beforeend',`<div class="modal fade" id="${id}" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">${title}</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body">${body}<div class="text-danger mt-2 err"></div></div><div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary ok">${ok}</button></div></div></div></div>`);
 const el=$(id),m=new bootstrap.Modal(el);el.addEventListener('hidden.bs.modal',()=>el.remove());el.querySelector('.ok').onclick=async()=>{try{await onOk(el);m.hide()}catch(e){el.querySelector('.err').textContent=e.message}};m.show();return el}
